const { room_id, celsius, measured_at_ms } = $json.message ?? {};

if (room_id !== 'cold-01' && room_id !== 'cold-02') {
  throw new Error('Nieznana chłodnia');
}

if (!Number.isFinite(celsius)) {
  throw new Error('Temperatura musi być liczbą');
}

if (
  !Number.isSafeInteger(measured_at_ms) ||
  measured_at_ms <= 0 ||
  measured_at_ms > 9_223_372_036_854
) {
  throw new Error('Nieprawidłowy czas pomiaru');
}

return {
  json: {
    room_id,
    celsius,
    measured_at: new Date(measured_at_ms).toISOString(),
    line: `temperature,room_id=${room_id} celsius=${celsius} ${measured_at_ms}`,
  },
};

